    Map<Integer, Integer> distances = new HashMap<>();
    Map<Integer, Integer> previous = new HashMap<>();
    for (int i = 0; i < n; i++) {
        distances.put(i, -1);
        previous.put(i, -1);
    }

    // Set the distance for node 0 to 0 and the previous node to -1
    distances.put(0, 0);
    previous.put(0, -1);

    // Initialize the queue to store the nodes to be visited
    Queue<Integer> queue = new LinkedList<>();
    queue.add(0);

    // Iterate through the edges and nodes
    while (!queue.isEmpty()) {
        int node = queue.poll();
        for (int i = 0; i < edges.length; i++) {
            int neighbor = edges[i][0] == node ? edges[i][1] : edges[i][0];
            if (hasApple[neighbor] && distances.get(neighbor) == -1) {
                distances.put(neighbor, distances.get(node) + 1);
                previous.put(neighbor, node);
                queue.add(neighbor);
            }
        }
    }

    // Find the shortest path from node 0 to the last node with an apple
    int distance = Integer.MAX_VALUE;
    int lastNode = -1;
    for (int i = 0; i < n; i++) {
        if (hasApple[i] && distances.get(i) != -1 && distances.get(i) < distance) {
            distance = distances.get(i);
            lastNode = i;
        }
    }

    // Return the minimum time required to collect all the apples and return to node 0
    return distance + 1;
}

