    int startNode = 0;
    // create a graph from the edges
    Graph graph = new Graph(edges);
    // create a boolean array to keep track of which nodes have been visited
    boolean[] visited = new boolean[n];
    // create a priority queue to keep track of the nodes to be visited
    PriorityQueue<Node> queue = new PriorityQueue<Node>();
    // add node 0 to the queue
    queue.offer(new Node(startNode, 0));
    // loop until the queue is empty
    while (!queue.isEmpty()) {
        // get the node with the minimum timeCost from the queue
        Node currentNode = queue.poll();
        // if the current node has been visited, skip it
        if (visited[currentNode.nodeId]) {
            continue;
        }
        // mark the current node as visited
        visited[currentNode.nodeId] = true;
        // if the current node has an apple, return the time cost so far
        if (hasApple[currentNode.nodeId]) {
            return currentNode.timeCost;
        }
        // add the neighbors of the current node to the queue
        for (int neighbor : graph.adjacentLists[currentNode.nodeId]) {
            queue.offer(new Node(neighbor, currentNode.timeCost + 1));
        }
    }
    // if all nodes have been visited and no apple was found, return 0
    return 0;
}

