    int numFactors = (int)Math.floor(Math.sqrt(n)) + 1;

    // Iterate from 1 to the number of factors and find the kth factor
    for (int i = 1; i <= numFactors; i++) {
        if (n % i == 0) {
            k--;
            if (k == 0) {
                return i;
            }
        }
    }

    // If we reach this point, it means that n has less than k factors, so we return -1
    return -1;
}

