    Point p1 = new Point(points[0][0], points[0][1]);
    Point p2 = new Point(points[1][0], points[1][1]);
    Point p3 = new Point(points[2][0], points[2][1]);
    if (p1.slopeTo(p2) != p2.slopeTo(p3) || p1.slopeTo(p3) != p3.slopeTo(p2)) {
        return false;
    }

    // Check if the points are in counterclockwise order
    Point p1p2 = p1.minus(p2);
    Point p2p3 = p2.minus(p3);
    if (p1p2.cross(p2p3) >= 0) {
        return false;
    }

    // If none of the above conditions are violated, the points form a boomerang
