public static int minPerfectSquareSum(int n) {
if (n <= 0) {
return 0;
}

int count = 0;
int i = 1;

while (i * i <= n) {
i++;
}

int j = i - 1;

while (j > 0) {
if (n - j * j <= 0) {
break;
}

j--;
}

